<?php require_once "../config/auth.php";requireLogin();require_once "../config/database.php";$uid=$_SESSION["user_id"];$eid=(int)($_GET["event_id"]??0);$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$rating=(int)$_POST["rating"];$comments=trim($_POST["comments"]);$s=$conn->prepare("INSERT INTO feedback(user_id,event_id,rating,comments) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comments=VALUES(comments),submitted_at=CURRENT_TIMESTAMP");$s->bind_param("iiis",$uid,$eid,$rating,$comments);$s->execute();$msg="Feedback submitted successfully!";}$s=$conn->prepare("SELECT event_name FROM events WHERE event_id=?");$s->bind_param("i",$eid);$s->execute();$event=$s->get_result()->fetch_assoc();?><!DOCTYPE html><html><head><title>Feedback</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Campus Clubs</div><div class="nav-links"><a href="my-events.php">My Events</a><a href="../logout.php">Logout</a></div></nav><div class="form-wrap"><div class="form-box"><h2>Event Feedback</h2><p><?=htmlspecialchars($event["event_name"]??"Event")?></p><?php if($msg):?><div class="alert"><?=htmlspecialchars($msg)?></div><?php endif;?><form method="post"><label>Rating</label><select name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select><label>Comments</label><textarea name="comments" rows="5"></textarea><button class="btn full">Submit Feedback</button></form></div></div></body></html>